static private boolean declaredInside(List<FType> ts, SingleFcn f, List<FType> d) {
    if (ownGeneric(f)) return instanceHolding(f, ts, true) != null;
    return FTypeTuple.make(ts).subtypeOf(FTypeTuple.make(d));
}

